create table private.hub_saw_invoice_lines_v1 (
 tenant_id uuid not null, unit_id uuid not null references public.hub_objects(id),
 source_file text not null,source_sha256 text not null,line_number integer not null,
 article text not null,document text not null,occurred_on date not null,
 quantity numeric not null,unit text not null,amount numeric not null,
 primary key(tenant_id,source_sha256,line_number));
alter table private.hub_saw_invoice_lines_v1 enable row level security;
revoke all on private.hub_saw_invoice_lines_v1 from public,anon,authenticated;
do $$begin
 if (select count(*) from private.hub_saw_activity_rules_v1)<>1 then raise exception 'Expected one confirmed saw activity tenant';end if;
end $$;
